package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class NamibiaPopulationRoundingTest {
 private static final String NA="na-nied-primary-2024-v1";
 private void verify(Question q){int[] v=YearFiveNumberStories.read(q);assertNotNull(v);int n=v[0],unit=v[1],digit=n/(unit/10)%10,base=n/unit*unit,extra=digit>=5?unit:0,answer=base+extra;q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+answer)).correct());assertFalse(new Checker().check(q,List.of(),List.of(""+(answer+1))).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertFalse(h.canTransfer());List<String> inputs=List.of(""+n,""+unit,""+digit,digit>=5?"raise":"keep",""+base,""+extra,""+answer);for(int i=0;i<7;i++)assertTrue(h.step(i).accepts(inputs.get(i)));}
 @Test public void realCurriculumAllUnitsFreshAndPublicHelp(){var limits=GlobalCurriculum.limits(NA,YearFiveNumberStories.ROUND,6);Generator g=new Generator(new Random(256));List<String> recent=new ArrayList<>();Set<Integer> units=new HashSet<>();for(int i=0;i<150;i++){Question q=g.next(YearFiveNumberStories.ROUND,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=YearFiveNumberStories.read(q);assertTrue(v[0]>=0&&v[0]<=1000000);units.add(v[1]);verify(q);}assertEquals(Set.of(10,100,1000,10000,100000),units);}
 @Test public void endpointsHalfAndCarryRemainPublicAndBounded(){var limits=GlobalCurriculum.limits(NA,YearFiveNumberStories.ROUND,6);for(int unit:List.of(10,100,1000,10000,100000))for(int n:List.of(0,1,unit/2-1,unit/2,999999,1000000)){Question q=YearFiveNumberStories.rounding(n,unit);assertTrue(limits.allows(q));verify(q);}Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,NA);p.grade=6;assertTrue(GlobalCurriculum.available(p).stream().anyMatch(s->s.id.equals(YearFiveNumberStories.ROUND)));assertFalse(GlobalCurriculum.scope(p).stream().anyMatch(s->s.id.equals(YearFiveNumberStories.ROUND)));}
}
